// Good: prevent path traversal by canonicalizing and enforcing an allowed directory
import jakarta.servlet.*;
import jakarta.servlet.http.*;
import java.io.*;

@WebServlet("/file")
public class FileServlet extends HttpServlet {

    private static final String UPLOAD_DIR = "/var/www/uploads";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String fileName = req.getParameter("file");

        if (fileName == null || fileName.isEmpty()) {
            resp.sendError(400);
            return;
        }

        File baseDir = new File(UPLOAD_DIR).getCanonicalFile();
        File requestedFile = new File(UPLOAD_DIR, fileName).getCanonicalFile();

        // Only allow files that remain inside the intended directory
        if (!requestedFile.toPath().startsWith(baseDir.toPath())) {
            resp.sendError(403);
            return;
        }

        if (!requestedFile.exists() || !requestedFile.isFile()) {
            resp.sendError(404);
            return;
        }

        resp.setContentType("text/plain");
        try (BufferedReader reader = new BufferedReader(new FileReader(requestedFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                resp.getWriter().println(line);
            }
        }
    }
}

