import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class SafeUserServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws Exception {
        String name = request.getParameter("name");

        // fixed: validate input using a strict allowlist
        if (name == null || !name.matches("[A-Za-z0-9_]{1,50}")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid username");
            return;
        }

        // fixed: use a parameterized query so input is not interpreted as SQL
        try (Connection connection = DriverManager.getConnection(
                "jdbc:mysql://localhost:3306/app", "appUser", "secret");
             PreparedStatement statement = connection.prepareStatement(
                     "SELECT * FROM users WHERE username = ?")) {

            statement.setString(1, name);
            ResultSet resultSet = statement.executeQuery();

            if (resultSet.next()) {
                response.getWriter().write("Found user");
            } else {
                response.sendError(HttpServletResponse.SC_NOT_FOUND);
            }
        }
    }
}
