      "level_descriptors": {
        "1": "Communicates poorly, is unresponsive, and creates friction or misalignment.",
        "3": "Communicates clearly, collaborates respectfully, and keeps stakeholders informed.",
        "5": "Builds consensus, mentors others, and enables high-performing collaboration across teams."
      }
    },
    {
      "id": "impact",
      "name": "Business and Technical Impact",
      "weight": "5%",
      "description": "Measurable contribution to product success, system reliability, cost, customer value, or engineering excellence.",
      "indicators": [
        "Delivers features or improvements that support business goals",
        "Reduces incidents, technical debt, or operational cost",
        "Improves user experience, performance, or developer productivity",
        "Aligns engineering work with product strategy and customer needs",
        "Documents or shares impact with data where possible"
      ],
      "level_descriptors": {
        "1": "Work has little visible impact and frequently misses business or product objectives.",
        "3": "Contributes meaningfully to team goals and produces reliable, useful outcomes.",
        "5": "Creates significant measurable impact that advances product, platform, or organizational objectives."
      }
    }
  ],
  "overall_rating_guidance": {
    "1": "Do not meet the role's core requirements. Set an immediate improvement plan with clear expectations and follow-up checkpoints.",
    "2": "Below expectations. Identify specific gaps, provide coaching, and define short-term measurable goals.",
    "3": "Meets expectations. Recognize strengths and identify development areas for continued growth.",
    "4": "Exceeds expectations. Discuss increased responsibility, stretch assignments, or readiness for promotion where appropriate.",
    "5": "Exceptional. Consider high-visibility projects, leadership roles, awards, or career acceleration."
  },
  "review_process": [
    "Collect evidence from performance reviews, code quality metrics, incident reports, project delivery data, and peer feedback.",
    "Rate each criterion from 1 to 5 using the rating scale and level descriptors.",
    "Calculate a weighted overall score if a numeric rating is required.",
    "Document specific examples for strengths and areas for improvement.",
    "Agree on a development plan with measurable goals and a follow-up date."
  ]
}

