final_answer:
{
  "title": "Software Engineer Performance Review Rubric",
  "version": "1.0",
  "purpose": "Provide a consistent, evidence-based framework for evaluating software engineer performance across technical, delivery, collaboration, and growth dimensions.",
  "rating_scale": [
    {
      "score": 1,
      "label": "Unsatisfactory",
      "definition": "Consistently below expectations and requires immediate corrective action."
    },
    {
      "score": 2,
      "label": "Needs Improvement",
      "definition": "Partially meets expectations with material gaps in consistency, quality, or impact."
    },
    {
      "score": 3,
      "label": "Meets Expectations",
      "definition": "Reliably performs the role at the expected level for the position."
    },
    {
      "score": 4,
      "label": "Exceeds Expectations",
      "definition": "Regularly delivers above expectations with meaningful quality, speed, or influence."
    },
    {
      "score": 5,
      "label": "Outstanding",
      "definition": "Sets a benchmark for the team or organization and has broad, measurable impact."
    }
  ],
  "categories": [
    {
      "category": "Technical Excellence",
      "description": "Evaluates technical judgment, code quality, and problem-solving ability.",
      "criteria": [
        {
          "criterion": "Code Quality",
          "description": "Produces clean, readable, maintainable, and appropriately tested code.",
          "scoring_guidance": {
            "1": "Code is difficult to understand, lacks tests, or causes recurring defects.",
            "2": "Code quality is inconsistent and often requires rework.",
            "3": "Code is clear, reasonably tested, and maintainable.",
            "4": "Code is strong, well-tested, and improves maintainability for others.",
            "5": "Code is exemplary and serves as a model for best practices."
          }
        },
        {
          "criterion": "System Design",
          "description": "Designs or contributes to solutions with appropriate architecture, scalability, and tradeoff analysis.",
          "scoring_guidance": {
            "1": "Designs are unsound, missing key risks, or impractical.",
            "2": "Designs are basic and require significant guidance or revision.",
            "3": "Designs are appropriate for the problem scope and constraints.",
            "4": "Designs are robust, well-reasoned, and consider future growth.",
            "5": "Designs are innovative, influential, and set standards for complex systems."
          }
        },
        {
          "criterion": "Problem Solving",
          "description": "Diagnoses issues effectively and resolves technical challenges with sound reasoning.",
          "scoring_guidance": {
            "1": "Struggles to identify root causes and often escalates without sufficient analysis.",
            "2": "Problem solving is inconsistent and requires substantial support.",
            "3": "Effectively debugs and resolves typical issues independently.",
            "4": "Tackles complex or ambiguous problems with strong analytical depth.",
            "5": "Resolves the most difficult technical challenges and creates lasting solutions."
          }
        }
      ]
    },
    {
      "category": "Delivery and Impact",
      "description": "Evaluates the engineer's ability to ship work, meet commitments, and create value.",
      "criteria": [
        {
          "criterion": "Execution and Timeliness",
          "description": "Delivers work on time with quality and clear progress management.",
          "scoring_guidance": {
            "1": "Frequently misses deadlines without sufficient communication or planning.",
            "2": "Delivers unevenly and often needs reminders or close follow-up.",
            "3": "Reliably delivers work on schedule at the expected quality level.",
            "4": "Consistently meets or beats expectations while maintaining quality.",
            "5": "Delivers high-impact work ahead of schedule and de-risks complex initiatives."
          }
        },
        {
          "criterion": "Product and Business Impact",
          "description": "Connects technical work to user needs, product goals, and business outcomes.",
          "scoring_guidance": {
            "1": "Work is delivered without clear connection to product value.",
            "2": "Occasionally considers business or user impact but inconsistently.",
            "3": "Understands the product context and contributes appropriately.",
            "4": "Regularly makes decisions that improve product or business outcomes.",
            "5": "Drives high-impact technical choices that materially advance business goals."
          }
        },
        {
          "criterion": "Ownership and Accountability",
          "description": "Takes responsibility for outcomes, communicates blockers early, and follows through.",
          "scoring_guidance": {
            "1": "Avoids responsibility and does not follow through on commitments.",
            "2": "Needs frequent prompting to maintain ownership.",
            "3": "Takes ownership of assigned work and communicates status clearly.",
            "4": "Proactively manages risks, dependencies, and follow-through.",
            "5": "Owns outcomes end-to-end and raises the standard for accountability."
          }
        }
      ]
    },
    {
      "category": "Collaboration and Communication",
      "description": "Evaluates how effectively the engineer works with teammates, stakeholders, and the broader organization.",
      "criteria": [
        {
          "criterion": "Teamwork",
          "description": "Works productively with others to achieve shared goals.",
          "scoring_guidance": {
            "1": "Collaborates poorly and creates friction or confusion.",
            "2": "Participates in team work but with inconsistent engagement.",
            "3": "Works well with teammates and contributes to a constructive environment.",
            "4": "Actively supports teammates and improves team collaboration.",
            "5": "Is a unifying force who strengthens cross-functional collaboration."
          }
        },
        {
          "criterion": "Communication",
          "description": "Communicates clearly in meetings, documents, code reviews, and stakeholder discussions.",
          "scoring_guidance": {
            "1": "Communication is unclear, infrequent, or ineffective.",
            "2": "Communication is understandable but often incomplete or untimely.",
            "3": "Communicates clearly and appropriately for the audience.",
            "4": "Communicates with precision and helps others understand complex topics.",
            "5": "Expertly communicates complex technical topics across audiences and influences decisions."
          }
        },
        {
          "criterion": "Code Review and Feedback",
          "description": "Participates constructively in code review and gives or receives feedback effectively.",
          "scoring_guidance": {
            "1": "Avoids code review or provides feedback that is unhelpful or unconstructive.",
            "2": "Participates but inconsistently or with low impact.",
            "3": "Provides solid code reviews and accepts feedback professionally.",
            "4": "Provides high-quality feedback that improves quality and learning.",
            "5": "Elevates team practices through exceptionally insightful and constructive review culture."
          }
        }
      ]
    },
    {
      "category": "Growth and Professionalism",
      "description": "Evaluates learning, adaptability, and contribution to the team's long-term health.",
      "criteria": [
        {
          "criterion": "Learning and Adaptability",
          "description": "Learns new technologies, processes, and ways of working, and adapts to change.",
          "scoring_guidance": {
            "1": "Resists new approaches or fails to learn from experience.",
            "2": "Learns slowly and requires considerable support to adapt.",
            "3": "Learns effectively and adapts to new priorities or tools.",
            "4": "Learns quickly and applies new knowledge to improve work.",
            "5": "Accelerates team learning by mastering and disseminating new skills or techniques."
          }
        },
        {
          "criterion": "Mentorship and Knowledge Sharing",
          "description": "Helps others grow and shares knowledge through documentation, pairing, or guidance.",
          "scoring_guidance": {
            "1": "Rarely contributes to learning or development of others.",
            "2": "Occasionally helps others but not consistently.",
            "3": "Helps teammates and shares useful knowledge when asked.",
            "4": "Proactively mentors, documents, or trains others.",
            "5": "Strongly develops others and creates scalable learning resources."
          }
        },
        {
          "criterion": "Professionalism and Trust",
          "description": "Demonstrates reliability, integrity, and a commitment to team values.",
          "scoring_guidance": {
            "1": "Displays behavior that undermines trust or team effectiveness.",
            "2": "Professionalism is inconsistent.",
            "3": "Is reliable, respectful, and aligned with team norms.",
            "4": "Consistently earns trust through dependable and ethical conduct.",
            "5": "Models the highest standards of professionalism and strengthens team culture."
          }
        }
      ]
    }
  ],
  "review_guidance": {
    "evidence_expectations": [
      "Use specific examples from the review period, such as shipped work, incidents, design reviews, or peer feedback.",
      "Tie ratings to observed behavior and measurable outcomes wherever possible.",
      "Balance strengths and development areas rather than focusing only on negative examples."
    ],
    "development_planning": [
      "Identify 1 to 2 high-impact development goals for the next review period.",
      "Pair each goal with observable success criteria.",
      "Define support the manager or organization will provide, such as stretch projects, mentorship, training, or pairing."
    ],
    "calibration_questions": [
      "Is this rating supported by multiple examples rather than a single event?",
      "How does this performance compare to peers at the same level?",
      "What would need to change for this engineer to move up or down one level?"
    ]
  }
}

