<script>
(function(){
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* rhyme ticker */
  var words = ['BILL','HILL','DRILL','GRILL','SKILL','MILL','THRILL','SPILL','FILL','TILL','RILL','TRILL','QUILL','CHILL','STILL','WILL','PILL'];
  var half = '<span class="ticker-half">' + words.map(function(w){ return '<span class="tw">'+w+'</span><span class="sep">✳</span>'; }).join('') + '</span>';
  document.getElementById('tickerTrack').innerHTML = half + half;

  /* receipt date */
  document.getElementById('rdate').textContent =
    new Date().toLocaleDateString(undefined,{day:'2-digit',month:'short',year:'numeric'}).toUpperCase();

  /* tally */
  var items = Array.prototype.slice.call(document.querySelectorAll('.item'));
  var tallied = 0, settled = 0;
  var tT = document.getElementById('tTallied'), tS = document.getElementById('tSettled');
  var tallyEl = document.querySelector('.tally');
  function pad(n){ return String(n).padStart(2,'0'); }
  function update(){
    tT.textContent = pad(tallied);
    tS.textContent = pad(settled);
    tallyEl.classList.toggle('done', settled === 25);
    document.body.classList.toggle('balanced', settled === 25);
  }

  if (reduce){
    items.forEach(function(it){ it.classList.add('in'); });
    tallied = 25; update();
  } else {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting){
          e.target.classList.add('in');
          if (!e.target._seen){ e.target._seen = true; tallied++; update(); }
          io.unobserve(e.target);
        }
      });
    }, {threshold:.18});
    items.forEach(function(it){ io.observe(it); });
  }

  /* settle buttons */
  document.querySelectorAll('.settle').forEach(function(btn){
    btn.addEventListener('click', function(){
      var it = btn.closest('.item');
      it.classList.toggle('paid');
      var on = it.classList.contains('paid');
