    box-shadow:inset 0 0 0 1px rgba(37,28,17,.12);
  }

  /* ---------- ticker ---------- */
  .ticker{
    position:relative; z-index:10; overflow:hidden;
    background:var(--red); color:var(--paper);
    border-bottom:3px double rgba(37,28,17,.5);
    padding:.5em 0;
  }
  .ticker-track{display:inline-flex; white-space:nowrap; will-change:transform; animation:tick 52s linear infinite;}
  .ticker:hover .ticker-track{animation-play-state:paused;}
  @keyframes tick{to{transform:translateX(-50%);}}
  .ticker-set{display:inline-flex; align-items:center;}
  .tk{font-family:'Rye',serif; font-size:.78rem; letter-spacing:.18em; text-transform:uppercase; padding:0 1.1em;}
  .tk-sep{font-size:.85rem; opacity:.8;}

  /* ---------- masthead ---------- */
  .masthead{
    position:relative; text-align:center; z-index:10;
    max-width:1180px; margin:0 auto; padding:64px 32px 8px;
  }
  .watermark{
    position:absolute; inset:0; display:grid; place-items:center; z-index:-1;
    font-family:'Rye',serif; font-size:clamp(9rem,28vw,20rem); color:rgba(37,28,17,.05);
    transform:rotate(-8deg); user-select:none; pointer-events:none; line-height:1;
  }
  .orn{display:flex; align-items:center; gap:18px; color:var(--red); max-width:760px; margin:0 auto;}
  .orn::before,.orn::after{content:""; flex:1; border-top:3px double rgba(37,28,17,.55);}
  .orn span{font-size:1.3rem; letter-spacing:.6em; text-indent:.6em;}
  .kicker{
    margin-top:22px; font-size:.78rem; letter-spacing:.34em; text-transform:uppercase;
    color:var(--ink-soft);
  }
  .masthead h1{
    font-family:'Rye',serif; font-weight:400;
    font-size:clamp(3.1rem,10.5vw,7.6rem); line-height:.92; letter-spacing:.01em;
    margin:14px 0 6px;
  }
  .masthead h1 .bills{
    color:var(--red);
    text-shadow:3px 3px 0 rgba(37,28,17,.18);
    transition:letter-spacing .5s ease;
  }
  .masthead h1:hover .bills{letter-spacing:.05em;}
  .sub{font-style:italic; font-size:clamp(1.05rem,2.2vw,1.35rem); max-width:46ch; margin:14px auto 0; color:var(--ink-soft);}
  .price-line{
    margin-top:26px; font-size:.74rem; letter-spacing:.28em; text-transform:uppercase; color:var(--ink-soft);
  }
  .price-line b{color:var(--red); font-weight:400;}
  .mast-stamp{
    position:absolute; right:6%; top:44px; transform:rotate(7deg);
    font-family:'Rye',serif; font-size:.8rem; letter-spacing:.14em; text-transform:uppercase;
    color:var(--red); border:4px double var(--red); padding:.5em .8em; line-height:1.35; text-align:center;
    opacity:.9; mix-blend-mode:multiply;
  }
  .masthead .orn + .kicker{animation:rise .7s .15s both;}
  .masthead h1{animation:rise .7s .28s both;}
  .sub{animation:rise .7s .42s both;}
  .price-line{animation:rise .7s .55s both;}
  .mast-stamp{animation:stampin .5s .9s both cubic-bezier(.2,1.5,.4,1);}
  @keyframes rise{from{opacity:0; transform:translateY(22px);} to{opacity:1; transform:none;}}
  @keyframes stampin{from{opacity:0; transform:rotate(7deg) scale(2.4);} to{opacity:.9; transform:rotate(7deg) scale(1);}}

  /* ---------- layout ---------- */
  .wrap{position:relative; z-index:10; max-width:1180px; margin:0 auto; padding:12px 36px 140px;}
  .preface{
    display:grid; grid-template-columns:minmax(0,1fr) 220px; gap:48px; align-items:start;
    margin:52px auto 0; max-width:1000px;
  }
  .preface-body p{margin-bottom:1em; font-size:1.06rem;}
  .preface-body p:first-of-type::first-letter{
    font-family:'Rye',serif; font-size:3.7em; line-height:.78; float:left;
    padding:.06em .14em 0 0; color:var(--red);
  }
  .sig{font-family:'Homemade Apple',cursive; color:var(--blue); font-size:1.05rem; transform:rotate(-1deg);}
  .portrait figure{
    background:var(--card); border:1px solid var(--ink); padding:10px 10px 14px;
    box-shadow:5px 6px 0 rgba(37,28,17,.14); transform:rotate(1.4deg); transition:transform .35s ease;
  }
  .portrait figure:hover{transform:rotate(0deg) translateY(-4px);}
  .portrait img{width:100%; filter:sepia(.55) contrast(1.04) brightness(.97);}
  .portrait figcaption{font-family:'Homemade Apple',cursive; color:var(--blue); font-size:.92rem; margin-top:9px; text-align:center;}

  .main{display:grid; grid-template-columns:236px minmax(0,1fr); gap:60px; margin-top:64px;}

  /* ---------- contents ---------- */
  .index{
    position:sticky; top:28px; align-self:start; max-height:calc(100vh - 56px); overflow:auto;
    border-left:3px double rgba(160,50,34,.6); padding:4px 0 4px 18px;
    scrollbar-width:thin;
  }
  .index h3{
    font-family:'Rye',serif; font-weight:400; font-size:.95rem; letter-spacing:.2em;
    text-transform:uppercase; color:var(--red); margin-bottom:12px;
  }
  .index a{
    display:flex; gap:10px; align-items:baseline; text-decoration:none; color:var(--ink-soft);
    padding:4px 8px 4px 0; margin:1px 0; font-size:.95rem; position:relative;
    transition:color .25s, transform .25s;
  }
  .index a .rn{font-family:'Rye',serif; font-size:.72rem; color:var(--red); min-width:2.4em;}
  .index a::after{
    content:""; position:absolute; left:-2px; bottom:2px; height:1px; width:0; background:var(--red);
    transition:width .3s ease;
  }
  .index a:hover{color:var(--ink); transform:translateX(3px);}
  .index a:hover::after{width:calc(100% + 6px);}
  .index a.active{color:var(--red);}
  .index a.active::before{content:"❧ "; position:absolute; left:-19px; color:var(--red);}

  /* ---------- entries ---------- */
  .entry{
    display:grid; grid-template-columns:86px minmax(0,1fr); gap:26px;
    padding:26px 22px 24px; margin-bottom:30px; border:1px solid transparent;
    transition:border-color .35s, background .35s, box-shadow .35s;
  }
  .entry:hover{border-color:rgba(37,28,17,.18); background:rgba(255,252,240,.45); box-shadow:6px 8px 0 rgba(37,28,17,.06);}
  .reveal{opacity:0; transform:translateY(20px) rotate(-.4deg);}
  .reveal.in{opacity:1; transform:none; transition:opacity .65s ease, transform .65s ease;}
  .plate{
    align-self:start; width:86px; height:92px; border:3px double var(--ink);
    display:grid; place-items:center; position:relative;
    transform:rotate(-3deg); transition:transform .35s ease, background .35s ease, color .35s ease;
    background:rgba(255,252,240,.3);
  }
  .plate .rn{font-family:'Rye',serif; font-size:1.9rem; color:var(--red); transition:color .35s;}
  .plate .no{position:absolute; top:4px; left:0; right:0; font-size:.55rem; letter-spacing:.3em; text-transform:uppercase; text-align:center; color:var(--ink-soft);}
  .entry:hover .plate{transform:rotate(0deg); background:var(--red);}
  .entry:hover .plate .rn{color:var(--paper);}
  .entry:hover .plate .no{color:rgba(238,224,191,.85);}

  .entry h2{
    font-family:'Rye',serif; font-weight:400; font-size:clamp(1.35rem,2.6vw,1.8rem);
    letter-spacing:.03em; margin-bottom:4px;
  }
  .title-rule{height:3px; width:0; background:var(--red); margin-bottom:16px; transition:width .5s ease;}
  .entry:hover .title-rule{width:64px;}
  .limerick{font-size:1.24rem; line-height:1.72;}
  .line{
    display:block; padding:0 .35em; margin:1px 0 1px -.35em;
    background:linear-gradient(90deg, rgba(160,50,34,.14), rgba(160,50,34,.14)) no-repeat;
    background-size:0% 58%; background-position:0 52%; transition:background-size .4s ease;
  }
  .line:hover{background-size:100% 58%;}
  .note{
    margin-top:16px; max-width:48ch; font-family:'Homemade Apple',cursive;
    color:var(--blue); font-size:1.02rem; transform:rotate(-.6deg);
  }
  .note::before{content:"✎ "; }
  .actions{margin-top:16px; display:flex; flex-wrap:wrap; gap:10px;}
  .btn{
    font-family:'IM Fell English',serif; font-size:.86rem; letter-spacing:.1em;
    background:transparent; color:var(--ink); border:1.5px solid var(--ink);
    padding:.42em .95em; cursor:pointer;
    transition:background .25s, color .25s, transform .12s, box-shadow .25s;
  }
  .btn:hover{background:var(--ink); color:var(--paper); box-shadow:3px 3px 0 rgba(160,50,34,.4);}
  .btn:active{transform:translateY(2px); box-shadow:none;}
  .btn.talking{background:var(--red); border-color:var(--red); color:var(--paper); animation:pulse 1.1s ease-in-out infinite;}
  @keyframes pulse{50%{box-shadow:0 0 0 6px rgba(160,50,34,.18);}}
  .btn.done{background:var(--blue); border-color:var(--blue); color:var(--paper);}

  /* ---------- plates (photos) ---------- */
  .platefig{
    max-width:500px; margin:6px 0 44px; background:var(--card);
    border:1px solid var(--ink); padding:10px 10px 14px;
    box-shadow:5px 7px 0 rgba(37,28,17,.14); transform:rotate(-1.2deg);
    transition:transform .4s ease;
  }
  .platefig:nth-of-type(even){transform:rotate(1.1deg);}
  .platefig:hover{transform:rotate(0deg) translateY(-5px);}
  .platefig img{filter:sepia(.5) contrast(1.05) brightness(.97);}
  .platefig figcaption{font-family:'Homemade Apple',cursive; color:var(--blue); font-size:.95rem; margin-top:9px; display:flex; justify-content:space-between; gap:12px; flex-wrap:wrap;}
  .platefig figcaption b{font-family:'Rye',serif; font-weight:400; font-size:.72rem; letter-spacing:.2em; color:var(--red); text-transform:uppercase;}

  /* ---------- footer ---------- */
  .colophon{margin-top:80px; text-align:center;}
  .colophon p{font-size:.92rem; color:var(--ink-soft); max-width:64ch; margin:10px auto;}
  .colophon .kw{font-style:italic;}
  .colophon .kw b{color:var(--red); font-weight:400;}

  /* ---------- pint meter ---------- */
  .meter{
    position:fixed; right:26px; bottom:26px; z-index:65;
    background:var(--card); border:2px solid var(--ink); box-shadow:5px 5px 0 rgba(37,28,17,.22);
    padding:12px 16px 12px 12px; display:flex; align-items:center; gap:14px;
    transition:border-color .4s;
  }
  .meter.full{border-color:var(--red);}
  .glass{
    position:relative; width:46px; height:62px; padding:0; cursor:pointer;
    border:2.5px solid var(--ink); border-top-width:1.5px;
    clip-path:polygon(10% 0, 90% 0, 80% 100%, 20% 100%);
    background:linear-gradient(rgba(255,255,255,.4), rgba(255,255,255,.05));
    transition:transform .2s;
  }
  .glass:hover{transform:scale(1.06);}
  .fill{
    position:absolute; left:0; right:0; bottom:0; height:0%;
    background:linear-gradient(180deg,#dba036,#a8691b);
    transition:height .55s cubic-bezier(.2,.9,.3,1.25);
  }
  .foam{position:absolute; top:-4px; left:7%; right:7%; height:6px; background:var(--foam); border-radius:2px; box-shadow:0 1px 0 rgba(0,0,0,.18);}
  .meter.wob .glass{animation:wobble .5s ease;}
  @keyframes wobble{25%{transform:rotate(-8deg);} 60%{transform:rotate(7deg);} 100%{transform:rotate(0);}}
  .m-label{display:block; font-size:.58rem; letter-spacing:.28em; text-transform:uppercase; color:var(--ink-soft);}
  .m-count{font-family:'Rye',serif; font-size:1.05rem; color:var(--red); display:block; margin:2px 0 3px;}
  .m-reset{background:none; border:none; padding:0; font-family:'IM Fell English',serif; font-size:.72rem; font-style:italic; color:var(--blue); cursor:pointer; text-decoration:underline;}

  /* ---------- 25/25 overlay ---------- */
  .toast-ov{
    position:fixed; inset:0; z-index:80; display:grid; place-items:center;
    background:rgba(238,224,191,.72); opacity:0; pointer-events:none; transition:opacity .4s;
  }
  .toast-ov.show{opacity:1; pointer-events:auto;}
  .stamp-big{
    text-align:center; color:var(--red); border:10px double var(--red);
    padding:.25em .6em; transform:rotate(-8deg); background:rgba(238,224,191,.6);
  }
  .toast-ov.show .stamp-big{animation:stampin2 .5s cubic-bezier(.2,1.5,.4,1) both;}
  @keyframes stampin2{from{opacity:0; transform:rotate(-8deg) scale(2.8);} to{opacity:1; transform:rotate(-8deg) scale(1);}}
  .stamp-big h4{font-family:'Rye',serif; font-weight:400; font-size:clamp(3rem,11vw,7rem); line-height:1;}
  .stamp-big p{font-style:italic; margin:.6em 0 1em; font-size:1.05rem;}

  /* ---------- responsive ---------- */
  @media (max-width:980px){
    .main{grid-template-columns:1fr; gap:0;}
    .index{
      position:sticky; top:0; z-index:40; max-height:none; overflow-x:auto; overflow-y:hidden;
      display:flex; gap:8px; align-items:center; padding:10px 4px; border-left:none;
      background:var(--paper); border-bottom:2px solid rgba(160,50,34,.5); white-space:nowrap;
    }
    .index h3{margin:0 6px 0 0; font-size:.72rem;}
    .index a{border:1px solid rgba(37,28,17,.4); padding:.25em .7em; background:rgba(255,252,240,.5);}
    .index a .rn{min-width:auto; font-size:.6rem;}
    .index a.active{background:var(--red); color:var(--paper); border-color:var(--red);}
    .index a.active .rn{color:var(--paper);}
    .index a.active::before{content:none;}
    .preface{grid-template-columns:1fr;}
    .portrait{max-width:240px;}
    .entry{grid-template-columns:1fr; gap:14px; padding:20px 12px;}
    .plate{width:72px; height:76px;}
    .mast-stamp{position:static; display:inline-block; margin-top:18px;}
    .meter{right:14px; bottom:14px; padding:8px 12px 8px 8px;}
    .glass{width:38px; height:52px;}
    .wrap{padding:8px 20px 120px;}
  }
  @media (prefers-reduced-motion:reduce){
    html{scroll-behavior:auto;}
    .ticker-track,.glow,.btn.talking,.masthead *,.stamp-big{animation:none !important;}
    .ticker{overflow-x:auto;}
    .reveal{opacity:1; transform:none;}
    *{transition-duration:.01ms !important;}
  }
</style>
</head>
