    <!-- ══════════ THE TWENTY-FIVE ══════════ -->
    <section class="entries" id="entries">

      <article class="entry reveal" id="bill-1">
        <div class="plate"><span class="no">No.</span><span class="rn">I</span></div>
        <div>
          <h2>The Swindler</h2><div class="title-rule"></div>
          <div class="limerick">
            <span class="line">There was a young Bill, sharp as a quill,</span>
            <span class="line">Who'd fold up a bill with a thrill</span>
            <span class="line">For a debt to Herr Jurgen—</span>
            <span class="line">The same, very Herr Jurgen—</span>
            <span class="line">And settle every last bill.</span>
          </div>
          <p class="note">Herr Jurgen was never seen in the village again. Nor, for that matter, was the bill.</p>
          <div class="actions">
            <button class="btn speak">♪ Speak it</button>
            <button class="btn copy">⧉ Copy verse</button>
            <button class="btn toast">❖ Toast a pint</button>
          </div>
        </div>
      </article>

      <article class="entry reveal" id="bill-2">
        <div class="plate"><span class="no">No.</span><span class="rn">II</span></div>
        <div>
          <h2>The Economist</h2><div class="title-rule"></div>
          <div class="limerick">
            <span class="line">An economist Bill, in a book</span>
            <span class="line">On money, wrote, "A bill is a hook</span>
            <span class="line">That fishes a bill</span>
            <span class="line">Out of every last mill</span>
            <span class="line">And leaves you to cross on a brook."</span>
          </div>
          <p class="note">The book ran to two volumes. The second was a bill for the first.</p>
          <div class="actions">
            <button class="btn speak">♪ Speak it</button>
            <button class="btn copy">⧉ Copy verse</button>
            <button class="btn toast">❖ Toast a pint</button>
          </div>
        </div>
      </article>

      <article class="entry reveal" id="bill-3">
        <div class="plate"><span class="no">No.</span><span class="rn">III</span></div>
        <div>
          <h2>The Butcher</h2><div class="title-rule"></div>
          <div class="limerick">
            <span class="line">There was a young Bill, butcher, in Hack,</span>
            <span class="line">Who shaved a whole pound off the rack;</span>
            <span class="line">He'd weigh you a rump</span>
            <span class="line">That was, frankly, a stump,</span>
            <span class="line">And charge you the whole of the pack.</span>
          </div>
          <p class="note">The Hackney Market will not comment. The rump, we understand, did.</p>
          <div class="actions">
            <button class="btn speak">♪ Speak it</button>
            <button class="btn copy">⧉ Copy verse</button>
