(function(){
  "use strict";
  var reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ---------- ticker: populate from the 25 titles, seamless loop ---------- */
  var track = document.getElementById("tickerTrack");
  if (track) {
    var titles = Array.prototype.map.call(document.querySelectorAll(".entry h2"), function(h){
      var t = h.textContent.trim();
      return t.indexOf("Bill") === -1 ? "Bill " + t : t;
    });
    var set = function(ariaHidden){
      var s = document.createElement("span");
      s.className = "ticker-set";
      if (ariaHidden) s.setAttribute("aria-hidden","true");
      var lead = "<span class='tk'>Here comes Bill</span><span class='tk-sep'>❧</span>";
      var items = titles.map(function(t){
        return "<span class='tk'>" + t + "</span><span class='tk-sep'>❧</span>";
      }).join("");
      s.innerHTML = lead + items + lead;
      return s;
    };
    track.innerHTML = "";
    track.appendChild(set(false));
    track.appendChild(set(true));
  }

  /* ---------- scroll reveal ---------- */
  var revealables = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window && !reduced) {
    var io1 = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting) { e.target.classList.add("in"); io1.unobserve(e.target); }
      });
    }, { threshold: 0.12 });
    revealables.forEach(function(el){ io1.observe(el); });
  } else {
    revealables.forEach(function(el){ el.classList.add("in"); });
  }

  /* ---------- active index item ---------- */
  var indexLinks = Array.prototype.slice.call(document.querySelectorAll(".index a[href^='#bill-']"));
  if ("IntersectionObserver" in window && indexLinks.length) {
    var io2 = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting) {
          indexLinks.forEach(function(a){ a.classList.remove("active"); });
          var link = document.querySelector('.index a[href="#' + e.target.id + '"]');
          if (link) link.classList.add("active");
        }
      });
    }, { rootMargin: "-35% 0px -55% 0px" });
    document.querySelectorAll(".entry").forEach(function(el){ io2.observe(el); });
  }

  /* ---------- speak a limerick aloud ---------- */
  var synth = window.speechSynthesis;
  var speakingBtn = null;
  function pickVoice(){
    if (!synth) return null;
    var vs = synth.getVoices();
    return vs.find(function(v){ return /en-GB/i.test(v.lang) && /male/i.test(v.name); })
        || vs.find(function(v){ return /en-GB/i.test(v.lang); })
        || vs.find(function(v){ return /^en/i.test(v.lang); }) || null;
  }
  function resetSpeak(){
    if (speakingBtn) { speakingBtn.classList.remove("talking"); speakingBtn.textContent = "♪ Speak it"; speakingBtn = null; }
  }
  document.querySelectorAll(".btn.speak").forEach(function(btn){
    if (!synth) { btn.disabled = true; btn.style.opacity = .4; btn.title = "Not supported in this browser"; return; }
    btn.addEventListener("click", function(){
      if (speakingBtn === btn) { synth.cancel(); resetSpeak(); return; }
      synth.cancel(); resetSpeak();
      var text = Array.prototype.map.call(btn.closest(".entry").querySelectorAll(".line"), function(l){ return l.textContent.trim(); }).join(". ");
      var u = new SpeechSynthesisUtterance(text);
      u.rate = 0.94; u.pitch = 1.06;
      var v = pickVoice(); if (v) u.voice = v;
      u.onend = resetSpeak; u.onerror = resetSpeak;
      speakingBtn = btn; btn.classList.add("talking"); btn.textContent = "♪ Speakin'…";
      synth.speak(u);
    });
  });
  if (synth && synth.getVoices) { synth.getVoices(); synth.addEventListener && synth.addEventListener("voiceschanged", function(){}); }

  /* ---------- copy a verse ---------- */
  function copyText(t){
    if (navigator.clipboard && window.isSecureContext) return navigator.clipboard.writeText(t);
    return new Promise(function(res, rej){
      var ta = document.createElement("textarea");
      ta.value = t; ta.style.position = "fixed"; ta.style.opacity = "0";
      document.body.appendChild(ta); ta.select();
      try { document.execCommand("copy") ? res() : rej(); } catch(e){ rej(e); }
      ta.remove();
    });
  }
  document.querySelectorAll(".btn.copy").forEach(function(btn){
    btn.addEventListener("click", function(){
      var text = Array.prototype.map.call(btn.closest(".entry").querySelectorAll(".line"), function(l){ return l.textContent.trim(); }).join("\n");
      copyText(text).then(function(){
        var old = btn.textContent;
        btn.classList.add("done"); btn.textContent = "✓ Copied";
        setTimeout(function(){ btn.classList.remove("done"); btn.textContent = old; }, 1400);
      }).catch(function(){ btn.textContent = "✗ Sorry, no luck"; });
    });
  });

  /* ---------- pint counter ---------- */
  var KEY = "bills-toasted-count";
  var meter = document.getElementById("meter"),
      fill  = document.getElementById("fill"),
      count = document.getElementById("pintCount"),
      ov    = document.getElementById("toastOv");
  var toasts = parseInt(localStorage.getItem(KEY) || "0", 10);
  if (isNaN(toasts) || toasts < 0 || toasts > 25) toasts = 0;

  function apply(){
    fill.style.height = (toasts / 25 * 100) + "%";
    count.textContent = (toasts < 10 ? "0" : "") + toasts + " / 25";
    meter.classList.toggle("full", toasts === 25);
    ov.classList.toggle("show", toasts === 25);
    ov.setAttribute("aria-hidden", toasts === 25 ? "false" : "true");
  }
  function toast(){
    if (toasts >= 25) return;
    toasts++; localStorage.setItem(KEY, String(toasts));
    apply();
    if (!reduced) { meter.classList.remove("wob"); void meter.offsetWidth; meter.classList.add("wob"); }
  }
  function reset(){
    toasts = 0; localStorage.setItem(KEY, "0"); apply();
  }
  document.querySelectorAll(".btn.toast").forEach(function(b){ b.addEventListener("click", toast); });
  document.getElementById("glassBtn").addEventListener("click", toast);
  document.getElementById("pintReset").addEventListener("click", reset);
  document.getElementById("ovReset").addEventListener("click", reset);
  apply();
})();
</script>
</body>
</html>
```

**What's inside:**

- **25 original limericks**, one per Bill — the Swindler, the Economist, the Butcher, the Banker, the Old Bill from Peru, and more — with the required *bill*, *economist*, and *jurgen* woven into the verses, preface, annotations, and a little "index words" line in the colophon.
- **A working table of contents** that highlights the current limerick as you scroll (and becomes a sticky chip bar on mobile).
- **"Speak it" buttons** that read each verse aloud in a British-ish voice, **copy buttons**, and a **pint meter** that fills as you toast — at 25/25, a big red **"TO BILL!"** stamp slams on screen (progress saved in `localStorage`).
- Scrolling ticker, scroll-in reveals, ink-stamp number plates that flip red on hover, sepia "engraved plates," and full `prefers-reduced-motion` support.

