  .side-inner{position:sticky; top:1.4rem}
  .side h2{font-family:'IM Fell English SC',serif; font-weight:400; font-size:1.5rem; color:var(--gold); margin-bottom:.4rem}
  .side .side-sub{font-size:.95rem; font-style:italic; color:var(--paper-dim); margin-bottom:1rem}
  .toc{list-style:none; border-top:1px solid rgba(201,164,79,.3); margin-bottom:1.3rem}
  .toc a{
    display:flex; align-items:baseline; gap:.55rem; padding:.34rem .3rem;
    color:rgba(236,225,196,.72); text-decoration:none; font-size:1rem;
    position:relative; transition:color .25s, transform .25s;
  }
  .toc a:hover{color:#f3e9cd; transform:translateX(4px)}
  .toc a.now{color:var(--gold)}
  .toc a.now::before{content:""; position:absolute; left:-8px; top:15%; height:70%; width:3px; background:var(--gold)}
  .t-num{font-family:'Special Elite',monospace; font-size:.62rem; letter-spacing:.08em; min-width:2rem;
    color:var(--paper-dim); border:1px solid rgba(236,225,196,.25); border-radius:2px;
    text-align:center; padding:.1rem 0; transition:all .3s}
  .toc a.seen .t-num{background:var(--gold); color:var(--ink); border-color:var(--gold)}
  .toc a.now .t-num{background:var(--gold); color:var(--ink); border-color:var(--gold)}
  .t-name{white-space:nowrap}
  .t-dots{flex:1; border-bottom:1px dotted rgba(236,225,196,.3); transform:translateY(-4px)}
  .met{border:1px dashed rgba(201,164,79,.45); padding:.85rem .95rem; margin-bottom:1.2rem}
  .metbar{height:6px; background:rgba(255,255,255,.08); margin-bottom:.55rem; overflow:hidden}
  .metbar i{display:block; height:100%; width:0%; background:linear-gradient(90deg,var(--oxblood),var(--gold)); transition:width .6s cubic-bezier(.2,.7,.2,1)}
  .met p{font-family:'Special Elite',monospace; font-size:.7rem; letter-spacing:.14em; color:var(--paper-dim)}
  .met b{display:inline-block; color:var(--gold); font-size:1.05rem}
  .met b.pop{animation:pop .4s ease}
  @keyframes pop{40%{transform:scale(1.35)}}
  .btn{
    width:100%; font-family:'Special Elite',monospace; font-size:.7rem; letter-spacing:.16em; text-transform:uppercase;
    background:transparent; border:1px solid rgba(201,164,79,.55); color:#e9dcb4;
    padding:.7rem .9rem; margin-top:.6rem; cursor:pointer;
    transition:background .3s, transform .3s, box-shadow .3s;
  }
  .btn:hover{background:rgba(201,164,79,.14); transform:translateY(-2px); box-shadow:0 8px 18px -12px rgba(201,164,79,.6)}
  .btn:active{transform:translateY(0)}
  .btn .spin{display:inline-block; transition:transform .6s}
  .btn:hover .spin{transform:rotate(-260deg)}

  /* ---------- the folio of cards ---------- */
  .stack{display:flex; flex-direction:column; gap:2.3rem}
  .card{
    position:relative; cursor:pointer;
    background:linear-gradient(158deg,var(--parch-1),var(--parch-2) 68%,#e4d2a6);
    color:var(--ink); padding:1.7rem 1.9rem 1.15rem;
    border:1px solid rgba(43,32,22,.4);
    box-shadow:0 2px 0 rgba(0,0,0,.3), 0 18px 34px -22px rgba(0,0,0,.8);
    transform:rotate(var(--tilt,0deg));
    opacity:0; translate:0 28px;
    transition:opacity .7s ease, translate .7s cubic-bezier(.2,.7,.2,1), transform .45s cubic-bezier(.2,.7,.2,1), box-shadow .45s;
  }
  .card::before{content:""; position:absolute; inset:7px; border:1px solid rgba(43,32,22,.28); pointer-events:none}
  .card::after{content:""; position:absolute; inset:0; background-image:var(--noise); opacity:.13; mix-blend-mode:multiply; pointer-events:none}
  .card.in{opacity:1; translate:0 0}
  .card:hover{transform:rotate(0deg) translateY(-5px); box-shadow:0 4px 0 rgba(0,0,0,.3), 0 30px 46px -24px rgba(0,0,0,.85)}
  .stack.swap .card{opacity:0 !important; transform:translateY(14px) rotate(0deg) !important; transition-duration:.32s}
  .fleur{position:absolute; top:11px; left:15px; color:rgba(138,47,42,.45); font-size:1rem; transition:color .4s}
  .card:hover .fleur{color:rgba(138,47,42,.85)}
  .stamp{
    position:absolute; top:12px; right:15px;
    font-family:'Special Elite',monospace; font-size:.66rem; letter-spacing:.14em;
    color:var(--oxblood); border:1.5px solid currentColor; padding:.16rem .5rem .12rem;
    transform:rotate(6deg); opacity:.9; transition:transform .4s;
  }
  .card:hover .stamp{transform:rotate(2deg) scale(1.06)}
  .epithet{
    font-family:'IM Fell English SC',serif; font-weight:400; font-size:1.4rem;
    color:#3a2b18; display:flex; align-items:center; gap:.7rem; margin:.15rem 0 .5rem;
  }
  .epithet::after{content:""; flex:1; height:1px; background:rgba(43,32,22,.25)}
  .verse{margin-top:.4rem}
  .ln{font-size:1.3rem; line-height:1.55; margin:.14rem 0; opacity:0; transform:translateY(10px);
    transition:opacity .5s ease, transform .5s cubic-bezier(.2,.7,.2,1)}
  .card.in .ln{opacity:1; transform:none}
  .card.in .ln:nth-child(1){transition-delay:.12s}
  .card.in .ln:nth-child(2){transition-delay:.24s}
  .card.in .ln:nth-child(3){transition-delay:.36s}
  .card.in .ln:nth-child(4){transition-delay:.48s}
  .card.in .ln:nth-child(5){transition-delay:.60s}
  .verse p:first-child::first-letter{
    font-family:'IM Fell English SC',serif; font-size:3.3em; float:left;
    line-height:.78; padding:.05em .1em 0 0; color:var(--oxblood);
  }
  .r{font-style:italic; font-weight:500; color:#4a3115; transition:color .3s, text-shadow .3s}
  .r sup{font-family:'Special Elite',monospace; font-size:.5em; top:-.65em; color:rgba(138,47,42,.8); margin-left:.08em}
  .card:hover .r{color:#7c4f10}
  .ln.hit{transform:translateY(-2px)}
  .ln.hit .r{color:var(--gold-deep); text-shadow:0 0 14px rgba(201,164,79,.65)}
  .note{margin-top:.85rem; font-style:italic; font-size:1rem; color:rgba(58,43,24,.72)}
  .note::before{content:"† "; color:var(--oxblood)}
  .cardfoot{
    display:flex; justify-content:space-between; align-items:center; gap:1rem;
    margin-top:1rem; padding-top:.7rem; border-top:1px dashed rgba(43,32,22,.32);
  }
  .scheme{font-family:'Special Elite',monospace; font-size:.58rem; letter-spacing:.16em; color:rgba(43,32,22,.55)}
  .recite{
    font-family:'Special Elite',monospace; font-size:.64rem; letter-spacing:.14em; text-transform:uppercase;
    background:rgba(138,47,42,.08); border:1px solid rgba(138,47,42,.55); color:var(--oxblood);
    padding:.34rem .75rem; cursor:pointer; transition:background .3s, color .3s, transform .3s;
  }
  .recite:hover{background:var(--oxblood); color:var(--parch-1); transform:translateY(-1px)}
  .recite:disabled{opacity:.55; cursor:default; transform:none}
  .meter{display:flex; align-items:center; gap:6px; margin-top:.75rem}
  .meter i{width:6px; height:6px; border-radius:50%; background:rgba(43,32,22,.22); transition:background .3s}
  .meter i.dum{width:10px; height:10px; background:rgba(138,47,42,.4)}
  .card:hover .meter i{background:rgba(176,122,18,.55)}
  .card.reciting .meter i{animation:beat .62s ease-in-out infinite; animation-delay:calc(var(--i)*.11s)}
  @keyframes beat{0%,100%{transform:scale(1)}30%{transform:scale(1.55); background:var(--gold-deep)}}

  /* ---------- colophon ---------- */
  footer{position:relative; z-index:1; max-width:1200px; margin:0 auto;
    padding:0 clamp(1rem,4vw,2.5rem) 3.4rem;
    border-top:1px solid rgba(201,164,79,.4);
    box-shadow:0 -5px 0 -4px rgba(201,164,79,.35)}
  .asterism{text-align:center; font-size:1.2rem; color:var(--oxblood); filter:brightness(1.6); padding:1.6rem 0 .2rem; letter-spacing:1em}
  .colo{max-width:62ch; margin:0 auto; font-size:1.06rem; line-height:1.7; color:var(--paper-dim); text-align:center; font-style:italic}
  .fine{margin-top:1.4rem; text-align:center; font-family:'Special Elite',monospace; font-size:.62rem; letter-spacing:.22em; text-transform:uppercase; color:rgba(236,225,196,.4)}

  /* ---------- responsive ---------- */
  @media (max-width:920px){
    .shell{grid-template-columns:1fr}
    .side-inner{position:static}
    .toc{columns:2; column-gap:1.6rem}
    .mastgrid{grid-template-columns:1fr}
    .facts{width:min(360px,100%)}
  }
  @media (max-width:620px){
    .toprule span:nth-child(2){display:none}
    .toc{columns:1}
    .card{padding:1.4rem 1.2rem 1rem}
    .ln{font-size:1.18rem}
  }
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{animation:none !important; transition:none !important}
    .card{opacity:1; translate:0 0; transform:none}
    .ln{opacity:1; transform:none}
    h1 .mask>span{transform:none}
  }
</style>
</head>
<body>

<div class="bmark" aria-hidden="true">B</div>
<div class="motes" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div>

<header>
  <div class="toprule">
    <span>Broadside · No. XXV</span>
    <span>The Limerick Gazette</span>
    <span>Anno MMXXV</span>
  </div>
  <div class="mastgrid">
    <div>
      <p class="over">Twenty-five verse portraits of the various</p>
      <h1>
        <span class="mask"><span class="m1">The Complete</span></span>
        <span class="mask"><span class="m2">Limericks</span></span>
        <span class="mask"><span class="m3">of <em>Bill</em>.</span></span>
      </h1>
      <p class="under">One for every bill in the kingdom, set in the old anapestic measure and bound without apology. Read them aloud, in a pub, at a moderate volume.</p>
      <div class="meterstrip" aria-hidden="true">
        <span class="lbl">the measure</span>
        <span class="dots"><i></i><i class="dum"></i><i></i><i class="dum"></i><i></i></span>
        <span class="lbl">da · DUM · da · DUM · da — × 25</span>
      </div>
    </div>
    <aside class="facts" aria-label="Catalogue card">
      <span class="price">TWOPENCE</span>
      <h2>Catalogue Card</h2>
      <dl>
        <div class="fact"><dt>Contents</dt><span class="lead"></span><dd>25 × BILL</dd></div>
        <div class="fact"><dt>Economist</dt><span class="lead"></span><dd>1 (opinionated)</dd></div>
        <div class="fact"><dt>Jurgen</dt><span class="lead"></span><dd>1 (the butcher)</dd></div>
        <div class="fact"><dt>Invoices</dt><span class="lead"></span><dd>2, unpaid</dd></div>
        <div class="fact"><dt>Cats</dt><span class="lead"></span><dd>1, medium thickness</dd></div>
        <div class="fact"><dt>Whales</dt><span class="lead"></span><dd>1, courteous</dd></div>
        <div class="fact"><dt>Meter</dt><span class="lead"></span><dd>anapestic</dd></div>
        <div class="fact"><dt>Price</dt><span class="lead"></span><dd>one bill</dd></div>
      </dl>
    </aside>
  </div>
</header>

<div class="ticker" aria-hidden="true"><div class="tick" id="tick"></div></div>

<div class="shell">
  <aside class="side">
    <div class="side-inner">
      <h2>Index of the Twenty-Five</h2>
      <p class="side-sub">each entry, one bill, one fate</p>
      <ol class="toc" id="toc"></ol>
      <div class="met">
        <div class="metbar"><i id="bar"></i></div>
        <p><b id="metCount">0</b> OF 25 BILLS MET</p>
      </div>
      <button class="btn" id="shuffleBtn" type="button"><span class="spin">⟲</span>&nbsp; Shuffle the folio</button>
      <button class="btn" id="nextBtn" type="button">▶&nbsp; Recite the next unmet</button>
    </div>
  </aside>

  <main class="stack" id="stack">

    <article class="card" id="l1" data-short="The Astronaut" style="--tilt:-.55deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. I</span>
      <h3 class="epithet">Bill the Astronaut</h3>
      <div class="verse">
        <p class="ln">The astronaut, Bill, on the <span class="r">moon<sup>a</sup></span>,</p>
        <p class="ln">in a leaky old tin-can <span class="r">balloon<sup>a</sup></span>,</p>
        <p class="ln">he called his old <span class="r">gal<sup>b</sup></span>,</p>
        <p class="ln">he said, “Ruth — you’re a <span class="r">pal<sup>b</sup></span> —</p>
        <p class="ln">come and meet me for lunch with a <span class="r">spoon<sup>a</sup></span>.”</p>
      </div>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
      <div class="meter" aria-hidden="true"><i style="--i:0"></i><i class="dum" style="--i:1"></i><i style="--i:2"></i><i class="dum" style="--i:3"></i><i style="--i:4"></i></div>
    </article>

    <article class="card" id="l2" data-short="The Baker" style="--tilt:.4deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. II</span>
      <h3 class="epithet">Bill the Baker</h3>
      <div class="verse">
        <p class="ln">The baker, our friend called <span class="r">Bill<sup>a</sup></span>,</p>
        <p class="ln">would knead every loaf with a <span class="r">skill<sup>a</sup></span>;</p>
        <p class="ln">his sourdough would <span class="r">rise<sup>b</sup></span>,</p>
        <p class="ln">to the clouds in the <span class="r">skies<sup>b</sup></span>,</p>
        <p class="ln">and it flattened the cat — it was <span class="r">still<sup>a</sup></span>.</p>
      </div>
      <p class="note">witness: the cat, now of medium thickness.</p>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
      <div class="meter" aria-hidden="true"><i style="--i:0"></i><i class="dum" style="--i:1"></i><i style="--i:2"></i><i class="dum" style="--i:3"></i><i style="--i:4"></i></div>
    </article>

    <article class="card" id="l3" data-short="The Barber" style="--tilt:-.3deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. III</span>
      <h3 class="epithet">Bill the Barber</h3>
      <div class="verse">
        <p class="ln">The barber, our friend called <span class="r">Bill<sup>a</sup></span>,</p>
        <p class="ln">with his shears was as quick as a <span class="r">mill<sup>a</sup></span>;</p>
        <p class="ln">he’d trim and he’d <span class="r">snip<sup>b</sup></span>,</p>
        <p class="ln">he’d go, “Scissors — <span class="r">clip!<sup>b</sup></span>”</p>
        <p class="ln">till his client was bald as a <span class="r">pill<sup>a</sup></span>.</p>
      </div>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
      <div class="meter" aria-hidden="true"><i style="--i:0"></i><i class="dum" style="--i:1"></i><i style="--i:2"></i><i class="dum" style="--i:3"></i><i style="--i:4"></i></div>
    </article>

    <article class="card" id="l4" data-short="The Boxer" style="--tilt:.6deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. IV</span>
      <h3 class="epithet">Bill the Boxer</h3>
      <div class="verse">
        <p class="ln">The boxer, the boxer, <span class="r">Bill<sup>a</sup></span>,</p>
        <p class="ln">he was made out of iron and <span class="r">will<sup>a</sup></span>;</p>
        <p class="ln">he jabbed and he’d <span class="r">hook<sup>b</sup></span>,</p>
        <p class="ln">and he’d knock out the <span class="r">cook<sup>b</sup></span>,</p>
        <p class="ln">and the referee — twice — with a <span class="r">will<sup>a</sup></span>.</p>
      </div>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
      <div class="meter" aria-hidden="true"><i style="--i:0"></i><i class="dum" style="--i:1"></i><i style="--i:2"></i><i class="dum" style="--i:3"></i><i style="--i:4"></i></div>
    </article>

    <article class="card" id="l5" data-short="The Butler" style="--tilt:-.45deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. V</span>
      <h3 class="epithet">Bill the Butler</h3>
      <div class="verse">
        <p class="ln">The butler, the quiet <span class="r">Bill<sup>a</sup></span>,</p>
        <p class="ln">could pour the claret with <span class="r">skill<sup>a</sup></span>;</p>
        <p class="ln">his silver, so <span class="r">bright<sup>b</sup></span>,</p>
        <p class="ln">made the count hold his <span class="r">sight<sup>b</sup></span>,</p>
        <p class="ln">and the dishes all shivered with a <span class="r">chill<sup>a</sup></span>.</p>
      </div>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
      <div class="meter" aria-hidden="true"><i style="--i:0"></i><i class="dum" style="--i:1"></i><i style="--i:2"></i><i class="dum" style="--i:3"></i><i style="--i:4"></i></div>
    </article>

    <article class="card" id="l6" data-short="The Carpenter" style="--tilt:.35deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. VI</span>
      <h3 class="epithet">Bill the Carpenter</h3>
      <div class="verse">
        <p class="ln">The carpenter, Bill, would <span class="r">declare<sup>a</sup></span>,</p>
        <p class="ln">that his table was level as <span class="r">air<sup>a</sup></span>;</p>
        <p class="ln">he’d drive in a <span class="r">nail<sup>b</sup></span>,</p>
        <p class="ln">he’d measure with <span class="r">scale<sup>b</sup></span>,</p>
        <p class="ln">and the table said, “Well — I’m <span class="r">square<sup>a</sup></span>.”</p>
      </div>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
      <div class="meter" aria-hidden="true"><i style="--i:0"></i><i class="dum" style="--i:1"></i><i style="--i:2"></i><i class="dum" style="--i:3"></i><i style="--i:4"></i></div>
    </article>

    <article class="card" id="l7" data-short="The Dentist" style="--tilt:-.6deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. VII</span>
      <h3 class="epithet">Bill the Dentist</h3>
      <div class="verse">
        <p class="ln">The dentist, the dentist, <span class="r">Bill<sup>a</sup></span>,</p>
        <p class="ln">would yank out a molar by <span class="r">will<sup>a</sup></span>;</p>
        <p class="ln">he’d go, “Sit right <span class="r">still<sup>b</sup></span>,”</p>
        <p class="ln">while his drill made a <span class="r">shrill<sup>b</sup></span>,</p>
        <p class="ln">and he’d bill you the sum of a <span class="r">mill<sup>a</sup></span>.</p>
      </div>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
      <div class="meter" aria-hidden="true"><i style="--i:0"></i><i class="dum" style="--i:1"></i><i style="--i:2"></i><i class="dum" style="--i:3"></i><i style="--i:4"></i></div>
    </article>

    <article class="card" id="l8" data-short="The Diver" style="--tilt:.5deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. VIII</span>
      <h3 class="epithet">Bill the Diver</h3>
      <div class="verse">
        <p class="ln">The diver, our pal called <span class="r">Bill<sup>a</sup></span>,</p>
        <p class="ln">once grabbed off a shark by the <span class="r">gill<sup>a</sup></span>;</p>
        <p class="ln">he dove in a<span class="r">gain<sup>b</sup></span>,</p>
        <p class="ln">past the coral, and <span class="r">then<sup>b</sup></span> —</p>
        <p class="ln">a jellyfish wearing a <span class="r">bill<sup>a</sup></span>.</p>
      </div>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
      <div class="meter" aria-hidden="true"><i style="--i:0"></i><i class="dum" style="--i:1"></i><i style="--i:2"></i><i class="dum" style="--i:3"></i><i style="--i:4"></i></div>
    </article>

    <article class="card" id="l9" data-short="The Economist" style="--tilt:-.35deg" tabindex="0">
      <span class="fleur" aria-hidden="true">❦</span><span class="stamp">No. IX</span>
      <h3 class="epithet">Bill the Economist</h3>
      <div class="verse">
        <p class="ln">The economist, Bill, would <span class="r">declare<sup>a</sup></span>,</p>
        <p class="ln">that the markets are fair and <span class="r">square<sup>a</sup></span>;</p>
        <p class="ln">he’d check every <span class="r">chart<sup>b</sup></span>,</p>
        <p class="ln">and he’d clutch at his <span class="r">heart<sup>b</sup></span>,</p>
        <p class="ln">and he’d mutter, “That’s not my <span class="r">affair<sup>a</sup></span>.”</p>
      </div>
      <p class="note">no markets were harmed; the economist was.</p>
      <div class="cardfoot"><span class="scheme">A·A·B·B·A — DA DUM DA DUM DA</span><button class="recite" type="button">Recite</button></div>
