<script>
(function(){
  const romans = ['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX','XXI','XXII','XXIII','XXIV','XXV'];
  const stack  = document.getElementById('stack');
  const cards  = Array.from(stack.querySelectorAll('.card'));
  const toc    = document.getElementById('toc');
  const tick   = document.getElementById('tick');
  const bar    = document.getElementById('bar');
  const count  = document.getElementById('metCount');
  const metSet = new Set();

  /* build the index (and the ticker) from the cards themselves */
  cards.forEach((c,i)=>{
    const li = document.createElement('li');
    const a  = document.createElement('a');
    a.href = '#'+c.id;
    a.innerHTML = '<span class="t-num">'+romans[i]+'</span><span class="t-name">'+c.dataset.short+'</span><span class="t-dots"></span>';
    a.addEventListener('click', e=>{ e.preventDefault(); c.scrollIntoView({behavior:'smooth', block:'center'}); });
    li.appendChild(a); toc.appendChild(li);
  });
  const items = cards.map((c,i)=>'<span>'+romans[i]+' · '+c.dataset.short.toUpperCase()+'</span><span class="sep">✳</span>').join('');
  tick.innerHTML = items + items;

  /* reveal on scroll + “met” tally */
  function updateMet(){
    count.textContent = metSet.size;
    bar.style.width = (metSet.size/cards.length*100) + '%';
    count.classList.remove('pop'); void count.offsetWidth; count.classList.add('pop');
    document.querySelectorAll('.toc a').forEach(a=>{
      a.classList.toggle('seen', metSet.has(a.getAttribute('href').slice(1)));
    });
  }
  const revealIO = new IntersectionObserver(entries=>{
    entries.forEach(e=>{
      if(!e.isIntersecting) return;
      e.target.classList.add('in');
      if(!e.target.dataset.met){ e.target.dataset.met = '1'; metSet.add(e.target.id); updateMet(); }
    });
  }, {threshold: .22});
  cards.forEach(c=>revealIO.observe(c));

  /* which card is in the reading window → highlight in index */
  const nowIO = new IntersectionObserver(entries=>{
    entries.forEach(e=>{
      if(!e.isIntersecting) return;
      document.querySelectorAll('.toc a').forEach(a=>
        a.classList.toggle('now', a.getAttribute('href') === '#'+e.target.id));
    });
  }, {rootMargin: '-42% 0px -52% 0px'});
  cards.forEach(c=>nowIO.observe(c));

  /* recite: line by line, rhymes flash, meter beats */
  function recite(card){
    if(card.classList.contains('reciting')) return;
    card.classList.add('reciting');
    const btn = card.querySelector('.recite');
    const old = btn.textContent;
    btn.textContent = '…reciting…'; btn.disabled = true;
    const lines = card.querySelectorAll('.ln');
    lines.forEach((ln,i)=>{
      setTimeout(()=>{
        ln.classList.add('hit');
        setTimeout(()=>ln.classList.remove('hit'), 430);
      }, 130 + i*330);
    });
    setTimeout(()=>{
      card.classList.remove('reciting');
      btn.textContent = old; btn.disabled = false;
    }, 130 + lines.length*330 + 320);
  }
  cards.forEach(c=>{
    c.addEventListener('click', ()=>recite(c));
    c.addEventListener('keydown', e=>{ if(e.key==='Enter'){ e.preventDefault(); recite(c); } });
    c.querySelector('.recite').addEventListener('click', e=>{ e.stopPropagation(); recite(c); });
  });

  /* shuffle the folio */
  let shuffling = false;
  document.getElementById('shuffleBtn').addEventListener('click', ()=>{
    if(shuffling) return; shuffling = true;
    cards.forEach(c=>c.classList.remove('in'));
    stack.classList.add('swap');
    setTimeout(()=>{
      for(let i=cards.length-1; i>0; i--){
        const j = Math.floor(Math.random()*(i+1));
        [cards[i],cards[j]] = [cards[j],cards[i]];
      }
      cards.forEach(c=>stack.appendChild(c));
      stack.classList.remove('swap');
      cards.forEach((c,i)=>setTimeout(()=>c.classList.add('in'), 80 + i*40));
      shuffling = false;
    }, 340);
  });

  /* recite the next unmet bill */
  document.getElementById('nextBtn').addEventListener('click', ()=>{
    const next = cards.find(c=>!c.dataset.met) || cards[0];
    next.scrollIntoView({behavior:'smooth', block:'center'});
    setTimeout(()=>recite(next), 650);
  });
})();
</script>
</body>
</html>
```

The page contains all 25 limericks (including Bill the Economist in No. IX and Bill the Fishmonger alongside Jurgen in No. XIV), the keywords **economist**, **bill**, and **jurgen** (in the verse, the catalogue card, marginalia, and colophon), plus a sticky running index, a "Bills met" counter, shuffling, and a per-card recite mode that flashes the rhyme words in A·A·B·B·A order.

